    cwd: input.cwd,
    env: process.env,
    input: apiKey,
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
  });

  const loginStdout = login.stdout || '';
  const loginStderr = login.stderr || '';
